import type { Lang, TourStopId } from '../data/types';

// Narration manifest reader (spec §3.8). The manifest is generated by
// scripts/generate-narration.py and committed under public/audio/narration/.
// Pure logic: no three.js, no DOM.

export interface Cue {
  startMs: number;
  endMs: number;
  text: string;
}

export interface NarrationSegment {
  file: string;
  durationMs: number;
  cues: Cue[];
}

export interface NarrationManifest {
  version: 1;
  segments: Record<TourStopId, Partial<Record<Lang, NarrationSegment>>>;
}

const MS_PER_WORD = 400;
const MIN_DURATION_MS = 4000;

/** Returns the cue active at `ms` (start inclusive, end exclusive), or null. */
export function cueAt(cues: Cue[], ms: number): Cue | null {
  for (const cue of cues) {
    if (ms >= cue.startMs && ms < cue.endMs) return cue;
  }
  return null;
}

/**
 * Subtitle-only duration estimate: 400 ms per word, at least 4000 ms. Words come from
 * `Intl.Segmenter` for the language, so Japanese (written without spaces) is counted
 * by dictionary words; punctuation is not a word.
 */
export function estimateDurationMs(text: string, lang: Lang): number {
  const segmenter = new Intl.Segmenter(lang, { granularity: 'word' });
  let words = 0;
  for (const s of segmenter.segment(text)) if (s.isWordLike) words++;
  return Math.max(MIN_DURATION_MS, words * MS_PER_WORD);
}

// A sentence ends at a run of . ! ? or the Japanese 。！？. A '.' between two digits
// (23.5) is a decimal point, not a terminator. Mirrors split_sentences() in Python.
const SENTENCE_RE = /(?:[^.!?。！？]|(?<=\d)\.(?=\d))+(?:[.!?。！？]+|$)/g;

function splitSentences(text: string): string[] {
  const parts = text.trim().match(SENTENCE_RE) ?? [];
  return parts.map((p) => p.trim()).filter((p) => p.length > 0);
}

// Mirrors fallback_cues() in scripts/generate-narration.py: cue boundaries are
// proportional to the character length of each sentence.
function proportionalCues(text: string, durationMs: number): Cue[] {
  const sentences = splitSentences(text);
  const total = sentences.reduce((sum, s) => sum + s.length, 0);
  if (sentences.length === 0 || total === 0) return [];
  const cues: Cue[] = [];
  let consumed = 0;
  let start = 0;
  sentences.forEach((sentence, i) => {
    consumed += sentence.length;
    const end =
      i === sentences.length - 1 ? durationMs : Math.round((durationMs * consumed) / total);
    cues.push({ startMs: start, endMs: end, text: sentence });
    start = end;
  });
  return cues;
}

/**
 * Resolves the narration for a stop. With a manifest entry for the language the
 * recorded audio is returned (audio:true). Otherwise the stop falls back to a
 * subtitle-only segment timed by estimateDurationMs (audio:false).
 */
export function resolveSegment(
  m: NarrationManifest | null,
  stopId: TourStopId,
  lang: Lang,
  scriptText: string,
): NarrationSegment & { audio: boolean } {
  const entry = m?.segments[stopId]?.[lang];
  if (entry) {
    return { file: entry.file, durationMs: entry.durationMs, cues: entry.cues, audio: true };
  }
  const durationMs = estimateDurationMs(scriptText, lang);
  return {
    file: '',
    durationMs,
    cues: proportionalCues(scriptText, durationMs),
    audio: false,
  };
}
